import {indiaChangeData as data} from './india-change-data.js?v=20261027-development04';
export {data as indiaChangeData};
export const indiaChangeViews={
 'dev-india-population':[['1994','Population in 1994'],['2024','Population in 2024'],['life','Longer lives'],['dividend','Potential and opportunity']],
 'dev-india-social-change':[['education','Education evidence'],['middle','Defined middle class'],['inequality','Income distribution'],['access','From access to learning']],
 'dev-india-geopolitics':[['links','Different partnerships'],['logistics','Read agreement terms'],['border','Dialogue and de-escalation'],['choices','Development trade-offs']],
 'dev-india-connectivity':[['connect','Complete a digital task'],['subscriptions','Urban and rural evidence'],['barriers','Who can participate?'],['transport','Deliver physical goods']],
 'dev-india-rapid-impacts':[['economy','Economic links'],['society','People and pressures'],['environment','Trace pollution pathways'],['balance','Compare stakeholders']]
};
export const indiaChangeRequirements=Object.fromEntries(Object.entries(indiaChangeViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const indiaChangeAnimated=(k,v)=>({'dev-india-population':['dividend'],'dev-india-social-change':['access'],'dev-india-geopolitics':['border'],'dev-india-connectivity':['connect','transport'],'dev-india-rapid-impacts':['economy','environment']}[k]||[]).includes(v);
export const sexToTotalPercent=(sexPercent,sexCount,total)=>sexPercent*sexCount/total;
export const connectionGap=()=>data.connectivity.values[0][1]-data.connectivity.values[1][1];
const readable=s=>String(s).replace(/([A-Za-z])(?=\d)/g,'$1 ').replace(/(\d)(?=[A-Za-z])/g,'$1 ');
const T=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${readable(s)}</text>`;
const line=(d,c='#b5cbd0',w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,r=5,c='#efb79c')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#eee9d9"/>`;
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?64:40}" rx="10" fill="#35566b" stroke="#a2bec7"/>`+T(x+10,y+24,a,12)+(b?T(x+10,y+47,b,11):'');
const title=s=>T(20,29,s,13);
const fig=(b,c)=>`<svg viewBox="0 0 440 350" style="background:#203e53;border-radius:12px" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#f0f1e9" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,s)=>`<a href="${u}" target="_blank" rel="noopener">${s}</a>`;
const source=k=>`<p class="geo-caption">${{
 population:link(data.population.metadata,'World Bank WDI / UN population estimates')+' · '+link('https://datacatalog.worldbank.org/public-licenses#cc-by','CC BY4.0')+'. API snapshot8October2026. Midyear1994/2024 estimates; converted from sex-specific shares to % of total population. National estimates, not a live census or a cohort forecast.',
 life:link('https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=IN','World Bank WDI:life expectancy at birth')+'. API snapshot8October2026;1994/2024, rounded to0.1year. Period mortality conditions, not everyone’s death age.',
 education:link(data.education.source,'Ministry of Education / UDISE+,7July2026')+'. NEP secondary ClassesIX–XII, not the old IX–X measure. Gross enrolment ratio is not attendance, attainment or every student’s experience.',
 middle:link(data.middle.source,'PRICE original ICE360 survey brief,p14')+'. People in households with annual income₹5–30lakh at2020–21prices. Survey estimates349→432million; not households or a universal class definition.',
 income:link(data.income.source,'Bharti,Chancel,Piketty,Somanchi,WIL2024/09 Table2')+'. 2022–23 research estimates of national-income shares by adult group. Not wealth or consumption inequality; top1% is nested in top10%. Middle40% does not define PRICE’s middle class. Source/data uncertainty remains.',
 links:link(data.agreements.quad.source,'2024 Quad project factsheet')+' · '+link('https://www.dfat.gov.au/international-relations/regional-architecture/quad','DFAT:Quad partnership')+'. Dated cooperation example; projects and commitments do not guarantee outcomes. India,Australia,Japan,USA; not an automatic mutual-defence alliance.',
 terms:link(data.agreements.lemoa.source,'Defence Ministry:LEMOA signed29August2016')+'. Facilitates reciprocal logistics; no obligation to carry out joint activity and no bases established by this agreement. Cooperation has specified terms, not unlimited commitments.',
 border:link(data.agreements.border.source,'MEA annual report2024,p77')+' · '+link(data.agreements.border.corroboration,'Chinese embassy:October2024 statement')+'. Patrolling/disengagement arrangements in specified areas, not a final boundary settlement or forecast of current relations. This schematic makes no territorial claim.',
 subscriptions:link(data.connectivity.source,'TRAI yearly indicators / PIB,5October2026')+'. Snapshot31March2026. Internet subscriptions per100population, not unique users, signal coverage or service quality. Urban/rural aggregates contain internal differences.',
 environment:link(data.water.source,'Jal Shakti24March2022:river-pollution mechanisms')+'. Sewage,industrial effluents,maintenance,dilution and other sources interact. No historical polluted-stretch count is presented as current.',
 impacts:link('https://www.worldbank.org/ext/en/country/india','World Bank:India development context')+' · '+link(data.water.source,'Jal Shakti:water-quality pressures')+'. Conditional mechanisms, not a measured national multiplier or proof of identical household outcomes.'
 }[k]}</p>`.split(/(<[^>]*>)/g).map(part=>part.startsWith('<')?part:readable(part)).join('');
const table=(cap,heads,rows)=>`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data"><caption>${cap}</caption><thead><tr>${heads.map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
export function indiaPyramid(year=2024,withTable=true){const p=data.population.years.find(p=>p.year===Number(year))||data.population.years[1];let b=title(`INDIA ${p.year} · AGE AND SEX STRUCTURE`)+T(55,54,'Male',12)+T(330,54,'Female',12);for(let n=0;n<=8;n+=2){const l=200-n*20,r=240+n*20;b+=line(`M${l} 65V279M${r} 65V279`,'#537582',.6)+T(l-3,296,String(n),10)+T(r-3,296,String(n),10);}for(const[i,a]of [...p.bins].reverse().entries()){const y=67+i*12.3,m=a.totalPercent.MA*20,f=a.totalPercent.FE*20;b+=`<rect x="${200-m}" y="${y}" width="${m}" height="10" rx="1" fill="#eeb498"/><rect x="240" y="${y}" width="${f}" height="10" rx="1" fill="#a8c4b2"/><text x="220" y="${y+8}" text-anchor="middle" font-size="10">${a.age}</text>`;}b+=T(70,319,'Each side: % of total population',12)+T(20,339,'Same 0–8% scale · oldest at top · 80+ open-ended',10);const graphic=fig(b,`${p.year} estimated population pyramid. Male bars extend left; female bars right. Every bar uses total population as its denominator. Sex categories follow the source; this is not an employment chart.`);if(!withTable)return graphic.slice(0,graphic.indexOf('</svg>')+6);return graphic+source('population')+(withTable?table(`${p.year}:converted shares of India’s total population`,['Age','Male %','Female %'],p.bins.map(a=>[a.age,a.totalPercent.MA.toFixed(2),a.totalPercent.FE.toFixed(2)])):'');}
export function indiaChangeEvidence(k='life'){
 if(k==='pyramids'){const[a,b]=data.population.years;return indiaPyramid(1994,false)+indiaPyramid(2024,false)+`<p class="geo-caption">Matched 1994/2024 estimated pyramids. Male left, female right; same0–8% scale; every bar is a share of total population. Age80+ is open-ended.</p>`+source('population')+table('Converted total-population percentages; M=male,F=female',['Age','1994 M%','1994 F%','2024 M%','2024 F%'],a.bins.map((x,i)=>[x.age,x.totalPercent.MA.toFixed(2),x.totalPercent.FE.toFixed(2),b.bins[i].totalPercent.MA.toFixed(2),b.bins[i].totalPercent.FE.toFixed(2)]));}
 if(k==='terms'){let b=title('LEMOA · READ THE SPECIFIC2016TERMS')+box(20,65,400,'Reciprocal logistics support','For authorised activities under agreed conditions')+box(20,150,400,'Cash payment or reciprocal support','Not automatically a free transfer')+box(20,235,400,'No obligation for joint activity','No bases established by this agreement');return fig(b,'Summary of specific terms in the Indian Defence Ministry’s30August2016 release, following signing on29August. Interpret the stated obligations.')+source('terms');}
 if(k==='income'){let b=title('INDIA2022–23 · NATIONAL-INCOME SHARES')+T(20,52,'Estimated adult groups · income share in%',11);for(const[i,[name,v]]of data.income.values.entries()){const y=95+i*73;b+=T(20,y,name,13)+`<rect x="20" y="${y+12}" width="${v*5.8}" height="25" rx="3" fill="${i===2?'#eeb498':'#a8c4b2'}"/>`+T(30+v*5.8,y+31,String(v),12);}b+=T(20,332,'Population-group size and income share are different.',11);return fig(b,'Estimated shares of national income for three non-overlapping adult groups. Read group definitions and values; the bars do not show numbers of people or wealth.')+source('income')+table('Estimated income distribution2022–23',['Adult group','National income %'],data.income.values);}
 let rows,max,heading,sub,unit,src;
 if(k==='life'){rows=data.population.years.map(p=>[String(p.year),Number(p.lifeExpectancy.toFixed(1))]);max=80;heading='INDIA · LIFE EXPECTANCY AT BIRTH';sub='Years · rounded estimates · common zero-based scale';unit='years';src='life';}
 else if(k==='education'){rows=data.education.values;max=100;heading='INDIA · SECONDARY GROSS ENROLMENT';sub='NEP ClassesIX–XII · ratio% · common scale';unit='%';src='education';}
 else if(k==='middle'){rows=data.middle.values;max=450;heading='PRICE · A DEFINED MIDDLE-CLASS GROUP';sub='Million people in qualifying households · estimates';unit='million';src='middle';}
 else{rows=data.connectivity.values;max=140;heading='INTERNET SUBSCRIPTIONS ·31MARCH2026';sub='Subscriptions per100people · common scale';unit='per100';src='subscriptions';}
 let b=title(heading)+T(20,53,sub,11);for(const[i,[name,v]]of rows.entries()){const y=103+i*102;b+=T(20,y,name,13)+`<rect x="20" y="${y+13}" width="${v/max*340}" height="29" rx="4" fill="${i?'#a8c4b2':'#eeb498'}"/>`+T(30+v/max*340,y+34,String(v),12);}b+=line('M20 295H360','#b5cbd0',1)+T(20,315,'0',10)+T(310,315,max+' '+unit,10);return fig(b,`${heading}. Values use a shared zero-based scale; read the stated period, unit and population before comparing.`)+source(src)+table(sub,['Period / group','Value ('+unit+')'],rows);
}
export function indiaChangeScene(k,v,t=0){if(!indiaChangeViews[k])return '';if(!indiaChangeRequirements[k].includes(v))v=indiaChangeRequirements[k][0];t=indiaChangeAnimated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',s='impacts';
 if(k==='dev-india-population'&&['1994','2024'].includes(v))return indiaPyramid(v);if(k==='dev-india-population'&&v==='life')return indiaChangeEvidence('life');if(k==='dev-india-social-change'&&v!=='access')return indiaChangeEvidence(v==='inequality'?'income':v);if(k==='dev-india-geopolitics'&&v==='logistics')return indiaChangeEvidence('terms');if(k==='dev-india-connectivity'&&v==='subscriptions')return indiaChangeEvidence('subscriptions');
 if(k==='dev-india-population'){s='population';b=title('POTENTIAL WORKFORCE → USABLE OPPORTUNITY')+box(20,70,180,'Working-age people','Not all are employed')+box(240,70,180,'Supporting conditions','Health / training / jobs')+box(120,245,200,'Participation / production','Opportunity is conditional')+line('M200 103H233M330 142L250 235')+dot(200+33*t,103)+dot(330-80*t,142+93*t)+T(20,330,'Ageing also changes care and income-security needs.',11);c='A conditional demographic-dividend pathway, not a count of jobs created or a cohort forecast. Tokens indicate enabling relationships, not measured people moving through time.';}
 if(k==='dev-india-social-change'){s='education';b=title('FROM ENROLMENT TO EFFECTIVE LEARNING')+box(20,65,180,'Place in education','Enrolment and access')+box(240,65,180,'Ability to participate','Time / affordability / support')+box(120,245,200,'Learning / opportunity','Teaching and progression')+line('M200 100H233M330 138L250 235')+dot(200+33*t,100)+dot(330-80*t,138+97*t)+T(20,329,'A higher enrolment ratio does not prove every outcome.',11);c='An educational access sequence. Reliability, inclusion and teaching shape participation; observed enrolment ratios do not establish every student’s attainment.';}
 if(k==='dev-india-geopolitics'){
 if(v==='links'){s='links';b=title('FOREIGN POLICY · DIFFERENT RELATIONSHIPS')+box(20,65,400,'Quad2024:India / Australia / Japan / USA','Health / infrastructure / maritime cooperation')+box(20,155,190,'Other partnerships','Trade / technology')+box(230,155,190,'Defence cooperation','Specific agreed duties')+box(20,260,400,'Read the obligations','Partnership ≠ automatic mutual defence');c='Selected relationship types, not a complete world alliance map. A partnership can contain security cooperation without creating every obligation of a formal military alliance.';}
 else if(v==='border'){s='border';b=title('DISPUTE → DIALOGUE → SPECIFIC ARRANGEMENTS')+box(20,65,180,'Boundary differences','Risks / uncertainty')+box(240,65,180,'Diplomacy + military talks','Negotiate arrangements')+box(120,245,200,'Implementation / review','Verify what changed')+line('M200 100H233M330 138L250 235M120 275L80 138')+dot(200+33*t,100)+dot(330-80*t,138+97*t)+dot(120-40*t,275-137*t)+T(20,331,'October2024 example: not a final boundary settlement.',10);c='A conceptual negotiation-and-verification sequence anchored in the dated India–China patrolling example. It does not simulate troop movements, determine sovereignty or predict current relations.';}
 else{s='terms';b=title('SECURITY AND DEVELOPMENT · COMPARE CHOICES')+box(20,65,190,'Possible gains','Stability / capabilities')+box(230,65,190,'Possible costs','Finance / tensions / risk')+box(20,180,400,'Opportunity cost','What alternative use of resources is forgone?')+box(20,270,400,'Evidence matters','Obligations / implementation / who gains');c='A static evaluation framework. Security and cooperation can support activity but use resources; no fabricated national cost or causal growth figure is implied.';}
 }
 if(k==='dev-india-connectivity'){s='subscriptions';
 if(v==='connect'){b=title('COMPLETE A TASK · NOT JUST A CONNECTION')+box(20,70,180,'Producer / learner','Device + power + skills')+box(240,70,180,'Usable digital service','Language + trust + access')+box(120,245,200,'Useful result','Sale / learning / information')+line('M200 102H233M330 138L250 235M120 275L80 138')+dot(200+33*t,102)+dot(330-80*t,138+97*t)+dot(120-40*t,275-137*t)+T(20,330,'Signals show steps, not unique users or measured gains.',11);c='A worked digital-task loop; successful use needs several conditions. Playback does not change the source subscription count or guarantee a sale, lesson or health outcome.';}
 else if(v==='barriers'){b=title('WHO CAN COMPLETE THE JOURNEY?')+box(20,65,190,'Infrastructure','Power / reliability / device')+box(230,65,190,'Affordability','Data / transport / time')+box(20,200,190,'Usability','Language / accessibility')+box(230,200,190,'Capability and trust','Skills / safe processes')+T(20,323,'Rural/urban averages do not describe every household.',11);c='An access checklist applied to different groups. These are conditions to evaluate, not measured shares of excluded people or fixed labels for all rural places.';}
 else{b=title('DIGITAL INFORMATION + PHYSICAL DELIVERY')+box(20,65,180,'Order / information','Online connection')+box(240,65,180,'Prepare goods','Storage / handling')+box(240,245,180,'Buyer receives goods','Roads / reliable transport')+box(20,245,180,'Producer can sell','Costs and prices still matter')+line('M200 100H233M330 138V235M235 277H205')+dot(200+33*t,100)+dot(330,138+97*t)+dot(235-30*t,277)+T(20,331,'Illustrative sequence; not an actual delivery route or rate.',10);c='Physical goods still require transport and logistics even when ordered online. Token timing is illustrative; better links do not ensure a profit or equal bargaining power.';}
 }
 if(k==='dev-india-rapid-impacts'){
 if(v==='economy'){b=title('TRACE A POSSIBLE ECONOMIC BENEFIT')+box(20,65,180,'Investment / activity','Production and services')+box(240,65,180,'Jobs / suppliers','Income and demand')+box(120,245,200,'Wider opportunities','Services / public revenues')+line('M200 100H233M330 138L250 235')+dot(200+33*t,100)+dot(330-80*t,138+97*t)+T(20,330,'Job quality, living costs and distribution affect gains.',11);c='Possible economic connections, not a measured multiplier. New activity may create demand and revenues; secure work and accessible services are not automatic.';}
 else if(v==='society'){b=title('SOCIAL CHANGE · BENEFITS AND PRESSURES')+box(20,65,190,'Potential improvements','Health / education / access')+box(230,65,190,'Potential pressures','Rents / commuting / services')+box(20,180,400,'Compare different people','Low-paid workers / families / displaced residents')+box(20,270,400,'Mixed effects can occur together','Ask about affordability, security and participation');c='A stakeholder comparison, not a claim that every project displaces people or that all households share the same gains and costs.';}
 else if(v==='environment'){s='environment';b=title('TRACE SOURCES AND TREATMENT TO THE RIVER')+box(20,60,180,'Homes / urban services','Sewage')+box(240,60,180,'Industrial activity','Effluents')+box(120,170,200,'Treatment / maintenance','Capacity and operation')+`<path d="M30 280Q160 260 250 290T420 280" fill="none" stroke="#8cbbc7" stroke-width="21"/>`+line('M110 130L175 160M330 130L260 160M220 239V270')+dot(110+65*t,130+30*t)+dot(330-70*t,130+30*t)+dot(220,239+31*t,5,'#d6baa0')+`<path d="M345 130L395 270" fill="none" stroke="#d6baa0" stroke-width="2" stroke-dasharray="4 4"/>`+dot(345+50*t,130+140*t,4,'#d6baa0')+T(344,205,'Bypass',10)+T(20,329,'Untreated / poorly treated discharges can add pollution.',11);c='Conceptual wastewater pathways, not actual concentrations, flow volumes or a measured river response. Treatment, upkeep, dilution and other sources affect water quality.';}
 else{b=title('MAKE A BALANCED, EVIDENCE-BASED JUDGEMENT')+box(20,65,190,'Workers / households','Pay / security / living costs')+box(230,65,190,'Firms / government','Supply / revenues / budgets')+box(20,190,190,'Residents elsewhere','Displacement / access / health')+box(230,190,190,'Environment','Water / air / habitats')+T(20,323,'Compare place, timescale, distribution and uncertainty.',11);c='A static judgement framework across social, economic and environmental effects. It does not assign invented weights or assert one universal national net benefit.';}
 }
 return fig(b,c)+source(s);
}
